     import { type ChildProcess, spawn } from 'node:child_process';
     import { createWriteStream, mkdirSync, type WriteStream } from 'node:fs';
     import { dirname } from 'node:path';
     import { createInterface } from 'node:readline';
     import type { Readable } from 'node:stream';

     import { EXIT_OK, EXIT_PAUSED } from 'spec-pipeline/protocol';

     const WARNING_PREFIX = 'spec-pipeline: WARNING';
     /** A child killed by a signal has no exit code: the shell convention for SIGINT. */
     const SIGNAL_EXIT = 130;
     /** The command could not start (ENOENT, EACCES): no pipeline ran. */
     const SPAWN_FAILED_EXIT = 1;

     const resultOf = (code: number | null): RunResult => {
       if (code === EXIT_OK) return { kind: 'done' };
       if (code === EXIT_PAUSED) return { kind: 'paused', code: EXIT_PAUSED };
       return { kind: 'failed', code: code ?? SIGNAL_EXIT };
     };

     const watchStderr = (stderr: Readable, log: WriteStream, onWarning: (line: string) => void): void => {
       createInterface({ input: stderr, crlfDelay: Infinity }).on('line', line => {
         log.write(`${line}\n`);
         if (line.startsWith(WARNING_PREFIX)) onWarning(line);
       });
     };

     const openLog = (file: string): WriteStream => {
       mkdirSync(dirname(file), { recursive: true });
       return createWriteStream(file, { flags: 'a' });
     };

     /** Settles once the child is gone AND the log is flushed; the SIGINT forwarder goes with it. */
     const awaitChild = (child: ChildProcess, log: WriteStream): Promise<RunResult> =>
       new Promise(resolve => {
         const forward = (): void => {
           child.kill('SIGINT');
         };
         const settle = (result: RunResult): void => {
           process.removeListener('SIGINT', forward);
           log.end(() => {
             resolve(result);
           });
         };
         process.once('SIGINT', forward);
         child.on('error', () => {
           settle({ kind: 'failed', code: SPAWN_FAILED_EXIT });
         });
         child.on('close', code => {
           settle(resultOf(code));
         });
       });

     export const runPipeline = (o: RunOptions): Promise<RunResult> => {
       const log = openLog(o.logFile);
       const [bin, ...rest] = o.command;
       const child = spawn(bin, [...rest, ...o.args], { cwd: o.cwd });
       child.stdout.pipe(log, { end: false });
       watchStderr(child.stderr, log, o.onWarning);
       return awaitChild(child, log);
     };
   'close' (not 'exit') is the resolve point: it fires after stdout/stderr are drained, and
   log.end's callback waits for the log to be flushed, so a test can read the log right after
   the await. The SIGINT listener is removed on settle: a once-listener left behind would leak
   one listener per stage run and forward a later Ctrl-C to a dead child.
